#include <iostream>
#include <queue>
#include <vector>
using namespace std;
using Graph = vector<vector<int>>;

Graph read_graph(int n, int m) {
    Graph adj(n + 1);
    for (int edge = 0; edge < m; ++edge) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
        adj[second].push_back(first);
    }
    return adj;
}

vector<int> find_reps(const Graph& adj) {
    int n = static_cast<int>(adj.size()) - 1;
    vector<bool> visited(n + 1, false);
    vector<int> reps;
    queue<int> pending;

    for (int start = 1; start <= n; ++start) {
        if (visited[start]) {
            continue;
        }
        reps.push_back(start);
        visited[start] = true;
        pending.push(start);
        while (!pending.empty()) {
            int vertex = pending.front();
            pending.pop();
            for (int next : adj[vertex]) {
                if (!visited[next]) {
                    visited[next] = true;
                    pending.push(next);
                }
            }
        }
    }
    return reps;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    Graph adj = read_graph(n, m);
    vector<int> reps = find_reps(adj);

    cout << static_cast<int>(reps.size()) - 1 << '\n';
    for (int i = 1; i < static_cast<int>(reps.size()); ++i) {
        cout << reps[0] << ' ' << reps[i] << '\n';
    }
    return 0;
}

